<?php
declare(strict_types=1);
require_once __DIR__.'/support-b-fixture.php';
use Hostider\Core\{Id,CanonicalJson};
use Hostider\Support\Mail\{Common,Commands,Tokens,Inbound,Outbound,Factory,Attachments};
function cCommand(array $f,string $action,array $p,?string $ref=null): array{$c=new Commands($f['mail']);$ref??=$f['admin']['reference'];$body=['action'=>$action,'payload'=>$p];$a=$c->command($ref,'prepare',$body,Id::uuid(),Id::uuid());$body['confirmation']=['id'=>$a['id'],'accepted'=>true];return $c->command($ref,'execute',$body,Id::uuid(),Id::uuid());}
function cFixture(bool $sla=false): array
{
    $f=supportFixture();$dep=$f['departments'][0];supportGrant($f,$dep);$a=$f['db']->execute('SELECT id FROM identity_assignments WHERE user_id=? AND customer_id IS NULL',[$f['admin']['user']])->fetchColumn();$f['db']->execute('INSERT INTO identity_grants(id,assignment_id,permission,customer_scope,department_scope) VALUES (?,?,?,?,?)',[Id::uuid(),$a,'support.mail_review','*',$dep]);$f['mail']=new Common($f['c']);$f['files']=Factory::files($f['mail']);$f['inbound']=new Inbound($f['mail'],$f['files']);$f['outbound']=new Outbound($f['mail']);cCommand($f,'retention',['department_id'=>$dep,'version'=>0,'enabled'=>true,'raw_days'=>7,'file_days'=>7]);if($sla){bPublish($f,bPolicy());}return $f;
}
function cRaw(array $f,array $changes=[],?array $who=null): string
{
    $who??=$f['client'];$h=array_replace(['From'=>$who['email'],'To'=>'support@example.invalid','Message-ID'=>'<'.Id::uuid().'@example.invalid>','Subject'=>'Synthetic mail','Content-Type'=>'text/plain; charset=utf-8'],$changes);$body=$h['BODY']??"Synthetic public message\r\n";unset($h['BODY']);$lines=[];foreach($h as $k=>$v){if($v!==null){$lines[]=$k.': '.$v;}}return implode("\r\n",$lines)."\r\n\r\n".$body;
}
function cMultipart(array $f,string $name='fixture.pdf',string $bytes=Attachments::FIXTURE): string{return cRaw($f,['Content-Type'=>'multipart/mixed; boundary="fixture"','BODY'=>"--fixture\r\nContent-Type: text/plain; charset=utf-8\r\n\r\nSynthetic multipart\r\n--fixture\r\nContent-Type: application/pdf\r\nContent-Disposition: attachment; filename=\"$name\"\r\nContent-Transfer-Encoding: base64\r\n\r\n".base64_encode($bytes)."\r\n--fixture--\r\n"]);}
function cProof(array $f,string $raw,?array $who=null): string{return (new Tokens($f['mail']))->proof(($who??$f['client'])['reference'],$f['departments'][0],hash('sha256',$raw));}
function cIn(array $f,string $raw,bool $verified=true,?array $who=null): array{return $f['inbound']->ingest($f['departments'][0],$raw,$verified?cProof($f,$raw,$who):'');}
function cDrain(array $f): void{$q=new \Hostider\Core\Queue\Queue($f['db']);$o=new \Hostider\Core\Queue\Outbox($f['db'],$q);while($o->dispatchOne()){}$w=new \Hostider\Core\Queue\Worker($f['db'],$q);(new \Hostider\Commerce\EventSink($f['db']))->register($w);(new \Hostider\Support\EventSink($f['db'],$f['config']))->register($w);(new \Hostider\Support\Work\HeldSink($f['db'],$f['config']))->register($w);$f['outbound']->register($w);while($w->once()){} }
function cDelivery(array $f,array $t): array{return $f['db']->execute('SELECT * FROM support_mail_outbound WHERE ticket_id=? ORDER BY created_at DESC,id DESC LIMIT 1',[$t['id']])->fetch();}
function cReplyRaw(array $f,array $t,?string $token=null,?array $who=null): string{$d=cDelivery($f,$t);$token??=(new Tokens($f['mail']))->reply(($who??$f['client'])['reference'],$t['id']);return cRaw($f,['Subject'=>'Re: '.$t['number'],'In-Reply-To'=>$d['message_ref'],'References'=>$d['message_ref'],'X-Hostider-Reply-Token'=>$token],$who);}
function cCounts(array $f): array{$out=[];foreach(['support_tickets','support_messages','support_events','support_sla_clocks','support_mail_inbound','support_mail_sources','support_mail_files','support_mail_outbound','support_mail_transport','support_mail_attempts','outbox_events','inbox_events','idempotency_keys'] as $t){$out[$t]=(int)$f['db']->execute('SELECT COUNT(*) FROM '.$t)->fetchColumn();}return $out;}
function cPost(HttpTestServer $s,string $action,array &$auth,string $operation,array $payload): array{$body=['action'=>$operation,'payload'=>$payload];$p=bHttp($s,'/api/v1/admin/support-mail/prepare',$auth,$body);same(200,$p[0]);$body['confirmation']=['id'=>$p[1]['data']['id'],'accepted'=>true];return bHttp($s,'/api/v1/admin/support-mail/execute',$auth,$body);}
function cRace(array $f,array $input,int $workers): array{$children=[];for($n=0;$n<$workers;++$n){$pipes=[];$p=proc_open([PHP_BINARY,__DIR__.'/support-c-child.php'],[0=>['pipe','r'],1=>['pipe','w'],2=>['pipe','w']],$pipes,null,bEnvironment($f));if(!is_resource($p)){throw new RuntimeException('Mail child unavailable');}fwrite($pipes[0],json_encode($input,JSON_THROW_ON_ERROR));fclose($pipes[0]);$children[]=[$p,$pipes];}$out=[];foreach($children as [$p,$pipes]){$raw=stream_get_contents($pipes[1]);$err=stream_get_contents($pipes[2]);fclose($pipes[1]);fclose($pipes[2]);same(0,proc_close($p));same('',$err);$out[]=json_decode($raw,true,32,JSON_THROW_ON_ERROR);}return $out;}
